const achievementLevels=[{at:1,name:'Primeira faísca',detail:'Seu primeiro objetivo concluído'},{at:25,name:'Aquecendo os motores',detail:'Um quarto da jornada'},{at:50,name:'Meio caminho, muita ciência',detail:'Metade dos objetivos'},{at:75,name:'Em alta temperatura',detail:'Três quartos da missão'},{at:100,name:'Temperatura máxima!',detail:'Todos os objetivos concluídos'}];
const $=s=>document.querySelector(s);let state={checks:{},dates:{}},storageOK=true;try{const saved=JSON.parse(localStorage.getItem('t17-n2-v1'));if(saved&&typeof saved==='object'){state.checks=saved.checks&&typeof saved.checks==='object'?saved.checks:{};state.dates=saved.dates&&typeof saved.dates==='object'?saved.dates:{}}}catch{storageOK=false}let selected=['SOI','HAM','IESC','MCM'].includes(document.documentElement.dataset.subject)?document.documentElement.dataset.subject:'all',expanded=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const key=(s,w,i)=>`${s}-${w}-${i}`;function save(){try{localStorage.setItem('t17-n2-v1',JSON.stringify(state))}catch{storageOK=false}$('#storageWarning').hidden=storageOK}function stats(s){let total=0,done=0;for(const [sub,data]of Object.entries(subjects)){if(s&&s!==sub)continue;for(const [w,t,c,items]of data.weeks)items.forEach((_,i)=>{total++;if(state.checks[key(sub,w,i)])done++})}return{total,done,percent:total?Math.round(done/total*100):0}}function updateStats(){const all=stats();renderThermometer();$('#percent').innerHTML=`${all.percent}<small>%</small>`;$('#progressBar').style.width=all.percent+'%';$('#progressText').textContent=`${all.done} de ${all.total} objetivos concluídos. ${all.done===all.total?'Checklist completo. Hora de revisar!':'Continue de onde parou.'}`;$('#subjects').innerHTML=Object.entries(subjects).map(([s,d])=>{const v=stats(s);return`<button class="subject ${selected===s?'active':''}" data-subject="${s}" style="--card-color:${d.color}" aria-label="Estudar ${s}"><div class="subject-top"><span class="subject-icon" aria-hidden="true">${d.icon}</span><span>↗</span></div><h3>${s}</h3><p>${d.name}</p><div class="bar"><span style="width:${v.percent}%"></span></div><div class="subject-foot"><span>${v.done}/${v.total} objetivos</span><b>${v.percent}%</b></div></button>`}).join('');$('#tabs').innerHTML=['all',...Object.keys(subjects)].map(s=>`<button data-tab="${s}" class="${s===selected?'active':''}" aria-pressed="${s===selected}">${s==='all'?'Todas':s}</button>`).join('')}
function renderWeeks(){const open=new Set([...document.querySelectorAll('details[open]')].map(x=>x.id)),q=norm($('#search').value.trim()),only=$('#pending').checked,wfilter=$('#week').value;let rendered=0,html='';for(const[s,d]of Object.entries(subjects)){if(selected!=='all'&&selected!==s)continue;for(const[w,title,category,items,note]of d.weeks){if(wfilter!=='all'&&Number(wfilter)!==w)continue;const matches=norm(`${s} ${title} ${category}`).includes(q);const indices=items.map((t,i)=>i).filter(i=>(!only||!state.checks[key(s,w,i)])&&(matches||norm(items[i]).includes(q)));if(items.length&&!indices.length)continue;if(!items.length&&(only||!matches))continue;rendered++;const done=items.filter((_,i)=>state.checks[key(s,w,i)]).length,id=`week-${s}-${w}`;html+=`<details class="week" id="${id}" ${expanded||open.has(id)||q?'open':''}><summary><span class="week-number"><small>SEM</small>${String(w).padStart(2,'0')}</span><div class="week-title"><h3>${esc(title)}</h3><span>${s} · ${esc(category)}${!items.length&&category==='Avaliação'?' · Registro N1':''}</span></div><span class="week-count">${items.length?`${done}/${items.length} checks`:category==='Avaliação'?'N1':'Em breve'}</span><span class="chevron" aria-hidden="true">⌄</span></summary>${items.length?`<div class="checklist">${indices.map(i=>{const k=key(s,w,i),checked=!!state.checks[k];return`<label class="objective ${checked?'done':''}"><input type="checkbox" data-key="${k}" ${checked?'checked':''}><span>${esc(items[i])}</span></label>`}).join('')}</div>`:`<p class="record">${esc(note)}</p>`}</details>`}}$('#weeks').innerHTML=html;$('#empty').hidden=rendered>0;$('#resultCount').textContent=`${rendered} blocos encontrados`}
const examDates={IESC:{date:'2026-10-22',start:'14:50',end:'16:50'},HAM:{date:'2026-10-28',start:'11:50',end:'13:50'},MCM:{date:'2026-11-04',start:'09:00',end:'11:00'},SOI:{date:'2026-11-05',start:'09:00',end:'11:00'}};
function examStatus(exam,now=Date.now()){const start=Date.parse(`${exam.date}T${exam.start}:00-03:00`),end=Date.parse(`${exam.date}T${exam.end}:00-03:00`);if(now>=end)return{label:'Prova encerrada',finished:true};if(now>=start)return{label:'Prova em andamento',active:true};const minutes=Math.ceil((start-now)/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),remaining=minutes%60;return{label:days>0?`Faltam ${days}d ${hours}h`:hours>0?`Faltam ${hours}h ${remaining}min`:`Faltam ${remaining}min`}}
function renderDates(){let next=true;$('#dates').innerHTML=Object.entries(examDates).map(([s,exam])=>{const status=examStatus(exam),isNext=next&&!status.finished;if(isNext)next=false;const[y,m,d]=exam.date.split('-');return `<article class="date ${isNext?'next-exam':''}"><b>${s}${status.active?' · EM ANDAMENTO':isNext?' · PRÓXIMA PROVA':''}</b><strong>${d}/${m}/${y}</strong><small>${status.label}</small><small style="margin-top:8px;font-weight:700;color:var(--ink)">${exam.start.replace(':','h')} às ${exam.end.replace(':','h')}</small></article>`}).join('')}

function select(s){selected=s;applySubject();updateStats();renderWeeks()}$('#subjects').addEventListener('click',e=>{const b=e.target.closest('[data-subject]');if(b){select(b.dataset.subject);location.hash='estudos';showPage()}});$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)select(b.dataset.tab)});$('#weeks').addEventListener('change',e=>{if(!e.target.dataset.key)return;state.checks[e.target.dataset.key]=e.target.checked;save();updateStats();const label=e.target.closest('label');label.classList.toggle('done',e.target.checked);const details=e.target.closest('details'),[_,s,w]=details.id.split('-'),items=subjects[s].weeks.find(v=>v[0]===Number(w))[3],done=items.filter((v,i)=>state.checks[key(s,w,i)]).length;details.querySelector('.week-count').textContent=`${done}/${items.length} checks`;if($('#pending').checked)renderWeeks()});$('#search').addEventListener('input',renderWeeks);$('#pending').addEventListener('change',renderWeeks);$('#week').addEventListener('change',renderWeeks);for(let w=2;w<=12;w++)$('#week').insertAdjacentHTML('beforeend',`<option value="${w}">${w}</option>`);$('#expand').onclick=()=>{expanded=!expanded;document.querySelectorAll('.week').forEach(d=>d.open=expanded);$('#expand').textContent=expanded?'Recolher todos':'Expandir todos'};$('#resume').onclick=()=>{$('#pending').checked=true;$('#search').value='';$('#week').value='all';renderWeeks();const first=$('.week');if(first){first.open=true;first.scrollIntoView({behavior:'smooth',block:'center'})}};$('#reset').onclick=()=>{if(confirm('Apagar todos os seus checks neste navegador?')){state.checks={};save();updateStats();renderWeeks()}};updateStats();renderWeeks();renderDates();$('#storageWarning').hidden=storageOK;

setInterval(renderDates,30000);

function applySubject(){document.documentElement.dataset.subject=selected;try{localStorage.setItem('t17-subject',selected)}catch{}const labels={all:'Todas as matérias',SOI:'SOI · vermelho',HAM:'HAM · verde',IESC:'IESC · azul',MCM:'MCM · laranja'};$('#focusPill').textContent=labels[selected];const messages={all:'Um check de cada vez. Você está construindo seu caminho.',SOI:'Conecte os mecanismos. Entenda o porquê. Bora de SOI!',HAM:'Olhar, ouvir, examinar. Seu próximo treino começa aqui!',IESC:'Pessoas, cuidado e território. Bora construir esse conhecimento!',MCM:'Pergunte, compare, interprete. A ciência está do seu lado!'};$('#focusMessage').textContent=messages[selected]}
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#themeToggle').setAttribute('aria-pressed',String(dark));$('#themeToggle').setAttribute('aria-label',dark?'Ativar tema claro':'Ativar tema escuro');$('#themeIcon').textContent=dark?'☀':'☾';$('#themeLabel').textContent=dark?'Claro':'Escuro';document.querySelector('meta[name="theme-color"]').content=dark?'#14111b':'#f8f7fa'}
$('#themeToggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('t17-theme',document.documentElement.dataset.theme)}catch{}syncTheme()};
function showPage(){const aliases={materias:'inicio',conteudos:'estudos'};let page=location.hash.slice(1)||'inicio';page=aliases[page]||page;if(!['inicio','estudos','calendario','dicas','progresso'].includes(page))page='inicio';document.querySelectorAll('.page-panel').forEach(p=>p.hidden=p.id!==page);document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',showPage);applySubject();syncTheme();showPage();


function renderThermometer(){const v=stats(),p=v.percent;const el=document.getElementById('thermometer');if(!el)return;el.setAttribute('aria-valuenow',String(p));document.getElementById('thermoFill').style.height=p+'%';document.getElementById('thermoDegrees').textContent=p+'°';document.getElementById('thermoPercent').textContent=p+'% dos objetivos';document.getElementById('thermoDone').textContent=v.done;document.getElementById('thermoTotal').textContent='de '+v.total+' objetivos';document.getElementById('thermoRemaining').textContent=v.total-v.done;const unlocked=achievementLevels.filter(a=>p>=a.at);document.getElementById('thermoBadges').textContent=unlocked.length+'/5';const current=p===100?['Temperatura máxima!','Missão cumprida. Agora é hora de revisar, descansar e confiar no seu preparo.']:p>=75?['Reta final aquecida','Você está muito perto da meta. Priorize o que ainda falta.']:p>=50?['O conhecimento ganhou calor','Metade da missão concluída. Continue no seu ritmo.']:p>=25?['A temperatura está subindo','Sua consistência está transformando planejamento em prática.']:p>0?['A primeira faísca acendeu','Cada check representa um objetivo trabalhado. Siga em frente.']:['Aquecimento iniciado','O primeiro check é o começo da sua jornada.'];document.getElementById('thermoTitle').textContent=current[0];document.getElementById('thermoMessage').textContent=current[1];document.getElementById('achievementGrid').innerHTML=achievementLevels.map(a=>'<article class="achievement '+(p>=a.at?'unlocked':'locked')+'"><span class="achievement-icon" aria-hidden="true">'+(p>=a.at?'✦':'◇')+'</span><span class="achievement-threshold">'+a.at+'°</span><h3>'+a.name+'</h3><p>'+a.detail+'</p><small>'+(p>=a.at?'Desbloqueada':'A desbloquear')+'</small></article>').join('');document.getElementById('thermoSubjects').innerHTML=Object.entries(subjects).map(([s,d])=>{const x=stats(s);return '<article><div><b>'+s+'</b><span>'+x.done+'/'+x.total+' objetivos · '+x.percent+'%</span></div><div class="bar"><span style="width:'+x.percent+'%;background:'+d.color+'"></span></div><button type="button" data-thermo-subject="'+s+'">Estudar '+s+' ↗</button></article>'}).join('')}
document.getElementById('thermoSubjects').addEventListener('click',e=>{const b=e.target.closest('[data-thermo-subject]');if(b){select(b.dataset.thermoSubject);location.hash='estudos'}});
renderThermometer();
